 public static bool FunRole(int theme,string role){return theme>=8&&new[]{"Arrow","Hand","Help","Pin","Person"}.Contains(role);}
 public static Point Hotspot(int theme,string role,int size){return FunRole(theme,role)?new Point((int)Math.Round(3*size/64f),(int)Math.Round(3*size/64f)):Hotspot(role,size);}
 public static Point Hotspot(string role,int size){float x=32,y=32;if(new[]{"Arrow","Help","Pin","Person"}.Contains(role)){x=4;y=4;}if(role=="AppStarting"){x=5;y=5;}if(role=="Hand"){x=8;y=4;}if(role=="UpArrow"){x=32;y=6;}if(role=="NWPen"){x=17;y=54;}return new Point((int)Math.Round(x*size/64f),(int)Math.Round(y*size/64f));}
 public static Bitmap Draw(int theme,string role,int size,int frame,int count) {
  Bitmap b=new Bitmap(size,size,PixelFormat.Format32bppArgb); using(Graphics g=Graphics.FromImage(b)) { g.ScaleTransform(size/64f,size/64f);g.SmoothingMode=theme==3?SmoothingMode.None:SmoothingMode.AntiAlias;
