   Color c=ColorTranslator.FromHtml(Colors[theme]); float phase=frame*6.283185f/count; if(theme==4||theme==5||theme==6)c=Hue((theme*49+frame*360f/count)%360); if(theme==7)c=Color.FromArgb((int)(100+110*(Math.Sin(phase)+1)/2),229,174);
