    else if(role.StartsWith("Size")) {g.TranslateTransform(32,32);if(role=="SizeNS")g.RotateTransform(90);if(role=="SizeNWSE")g.RotateTransform(45);if(role=="SizeNESW")g.RotateTransform(-45);PointF[] points={new PointF(-26,0),new PointF(-14,-11),new PointF(-14,-4),new PointF(14,-4),new PointF(14,-11),new PointF(26,0),new PointF(14,11),new PointF(14,4),new PointF(-14,4),new PointF(-14,11)};g.FillPolygon(brush,points);g.DrawPolygon(p,points);}
    else if(role=="No") {g.FillEllipse(brush,9,9,46,46);g.DrawEllipse(p,9,9,46,46);g.DrawLine(p,16,16,48,48);}
