 static Color ControlColor(Color c,float n){return Color.FromArgb((int)(c.R*n),(int)(c.G*n),(int)(c.B*n));}
 static void DrawClickArrow(Graphics g,int theme){g.SmoothingMode=SmoothingMode.AntiAlias;Color color=ColorTranslator.FromHtml(Colors[theme]);PointF[] points={new PointF(3,3),new PointF(4,17),new PointF(17,5)};using(var fill=new SolidBrush(color))using(var halo=new Pen(Color.White,2.8f))using(var outline=new Pen(ControlColor(color,.48f),.9f)){halo.LineJoin=outline.LineJoin=LineJoin.Round;g.DrawPolygon(halo,points);g.FillPolygon(fill,points);g.DrawPolygon(outline,points);}}
 static void Shape(Graphics g,Brush fill,Pen outline,PointF[] points){g.FillPolygon(fill,points);g.DrawPolygon(outline,points);}
