 static void Arrow(Graphics g,Pen p,Brush b,float scale,float x,float y,bool pixel) {var state=g.Save();g.TranslateTransform(x,y);g.ScaleTransform(scale,scale);PointF[] a=pixel?new[]{new PointF(4,4),new PointF(4,44),new PointF(12,44),new PointF(12,36),new PointF(20,36),new PointF(20,52),new PointF(28,52),new PointF(28,32),new PointF(40,32),new PointF(40,28)}:new[]{new PointF(4,4),new PointF(5,48),new PointF(17,36),new PointF(27,57),new PointF(36,53),new PointF(26,32),new PointF(44,32)};g.FillPolygon(b,a);g.DrawPolygon(p,a);g.Restore(state);}
 public static Color Hue(float hue){float x=1-Math.Abs(hue/60%2-1);float r=0,g=0,b=0;if(hue<60){r=1;g=x;}else if(hue<120){r=x;g=1;}else if(hue<180){g=1;b=x;}else if(hue<240){g=x;b=1;}else if(hue<300){r=x;b=1;}else {r=1;b=x;}return Color.FromArgb((int)(100+r*155),(int)(100+g*155),(int)(100+b*155));}
 public static byte[] Cur(Bitmap image,int hx,int hy) {int w=image.Width,h=image.Height,stride=((w+31)/32)*4;byte[] pixels=new byte[w*h*4];var locked=image.LockBits(new Rectangle(0,0,w,h),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{for(int y=0;y<h;y++)System.Runtime.InteropServices.Marshal.Copy(IntPtr.Add(locked.Scan0,y*locked.Stride),pixels,y*w*4,w*4);}finally{image.UnlockBits(locked);}using(var data=new MemoryStream())using(var bw=new BinaryWriter(data)){bw.Write(40);bw.Write(w);bw.Write(h*2);bw.Write((ushort)1);bw.Write((ushort)32);bw.Write(0);bw.Write(w*h*4+stride*h);bw.Write(0);bw.Write(0);bw.Write(0);bw.Write(0);for(int y=h-1;y>=0;y--)bw.Write(pixels,y*w*4,w*4);for(int y=h-1;y>=0;y--){byte[] mask=new byte[stride];for(int x=0;x<w;x++)if(pixels[(y*w+x)*4+3]==0)mask[x/8]|=(byte)(0x80>>(x%8));bw.Write(mask);}var dib=data.ToArray();using(var output=new MemoryStream())using(var o=new BinaryWriter(output)){o.Write((ushort)0);o.Write((ushort)2);o.Write((ushort)1);o.Write((byte)(w==256?0:w));o.Write((byte)(h==256?0:h));o.Write((byte)0);o.Write((byte)0);o.Write((ushort)hx);o.Write((ushort)hy);o.Write(dib.Length);o.Write(22);o.Write(dib);return output.ToArray();}} }
 static void Chunk(BinaryWriter w,string name,byte[] data){w.Write(Encoding.ASCII.GetBytes(name));w.Write(data.Length);w.Write(data);if(data.Length%2==1)w.Write((byte)0);}
 public static byte[] Ani(List<byte[]> frames,int rate) {return Ani(frames,Enumerable.Repeat(rate,frames.Count).ToArray());}
 public static byte[] Ani(List<byte[]> frames,int[] rates){using(var body=new MemoryStream())using(var w=new BinaryWriter(body)){w.Write(Encoding.ASCII.GetBytes("ACON"));using(var h=new MemoryStream())using(var a=new BinaryWriter(h)){foreach(int v in new[]{36,frames.Count,frames.Count,0,0,32,1,rates[0],1})a.Write(v);Chunk(w,"anih",h.ToArray());}using(var h=new MemoryStream())using(var a=new BinaryWriter(h)){foreach(int r in rates)a.Write(r);Chunk(w,"rate",h.ToArray());}using(var list=new MemoryStream())using(var l=new BinaryWriter(list)){l.Write(Encoding.ASCII.GetBytes("fram"));foreach(var f in frames)Chunk(l,"icon",f);Chunk(w,"LIST",list.ToArray());}using(var output=new MemoryStream())using(var o=new BinaryWriter(output)){Chunk(o,"RIFF",body.ToArray());return output.ToArray();}}}
 public static void ConvertImage(string path,string dest,int size,int hx,int hy) {using(var image=Image.FromFile(path)){if(image.Width>4096||image.Height>4096)throw new InvalidDataException("图片尺寸不可超过 4096×4096");int count=1;bool gif=Path.GetExtension(path).ToLowerInvariant()==".gif";if(gif)count=image.GetFrameCount(FrameDimension.Time);if(count>120)throw new InvalidDataException("GIF 不可超过 120 帧");var frames=new List<byte[]>();var rates=new List<int>();byte[] delays=null;try{delays=image.GetPropertyItem(0x5100).Value;}catch{}for(int i=0;i<count;i++){if(gif)image.SelectActiveFrame(FrameDimension.Time,i);using(var b=new Bitmap(size,size,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(b)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;float scale=Math.Min((float)size/image.Width,(float)size/image.Height);g.DrawImage(image,0,0,image.Width*scale,image.Height*scale);frames.Add(Cur(b,Math.Min(hx,size-1),Math.Min(hy,size-1)));}rates.Add(delays!=null&&delays.Length>=(i+1)*4?Math.Max(1,(int)(BitConverter.ToInt32(delays,i*4)*0.6)):6);}File.WriteAllBytes(dest,gif?Ani(frames,rates.ToArray()):frames[0]);}}
